# Initially generated by GitHub Copilot.
"""Render a JSON snippet as a BiDi-safe HTML <pre> block for authored docs.

The returned value is a raw-HTML htel (see mb_html.raw_html) containing a
<pre class="json-block"> element.  Hebrew-containing token spans get
``unicode-bidi:isolate; direction:rtl`` via the ``heb`` class, so the
browser treats each Hebrew fragment as an isolated RTL run within the
overall LTR JSON structure.
"""

import html as html_mod

from pygments import lex
from pygments.lexers import JsonLexer
from pygments.token import Token

from mb_misc import mb_html


def json_block_raw_html(json_text: str):
    """Return a raw-HTML htel containing <pre class="json-block">...</pre>."""
    return mb_html.raw_html(_build_pre_html(json_text))


# ---------------------------------------------------------------------------
# Internal helpers
# ---------------------------------------------------------------------------


def _token_color_class(ttype) -> str:
    if ttype is Token.Name.Tag:
        return "tok-key"
    if ttype in Token.Literal.String:
        return "tok-string"
    if ttype in Token.Literal.Number:
        return "tok-number"
    if ttype in Token.Keyword:
        return "tok-keyword"
    return "tok-punct"


def _has_hebrew(text: str) -> bool:
    return any("\u05d0" <= ch <= "\u05ea" or "\ufb1d" <= ch <= "\ufb4e" for ch in text)


def _has_pointing(text: str) -> bool:
    return any("\u0591" <= ch <= "\u05c7" for ch in text)


def _span(text: str, color_cls: str) -> str:
    escaped = html_mod.escape(text)
    classes = [color_cls]
    if _has_hebrew(text):
        classes.append("heb")
    if _has_pointing(text):
        classes.append("pointed")
    cls_attr = f' class="{" ".join(classes)}"'
    return f"<span{cls_attr}>{escaped}</span>"


def _build_pre_html(json_text: str) -> str:
    spans = [
        _span(value, _token_color_class(ttype))
        for ttype, value in lex(json_text, JsonLexer())
    ]
    code_html = "".join(spans)
    code_html = code_html.replace("...", '<span class="ellipsis">...</span>')
    return f'<pre class="json-block">{code_html}</pre>'
